def get_odd_collatz(n: int):
    if n <= 0:
        raise ValueError("n must be a positive integer")

    collatz_sequence = []
    current = n

    while current != 1:
        collatz_sequence.append(current)
        if current % 2 == 0:
            current //= 2
        else:
            current = 3 * current + 1
    collatz_sequence.append(1)  # Append the last term which is 1

    odd_numbers = sorted(num for num in collatz_sequence if num % 2 == 1)
    return odd_numbers

